import type { DataState } from "./types";
import raw from "../../data/bp18-progress-2026.json";

/**
 * The seed IS the real BP18 programme dataset.
 *
 * Source of truth: data/bp18-progress-2026.json, generated by
 * scripts/build-progress-data.py from the team's progress report
 * (Progress_13Nov2026.pdf). A shared, team-wide deployment must never invent
 * placeholder data, so both an empty database and "reset to seed" restore the
 * real thing — a wipe is recoverable instead of silently replacing the
 * programme with a demo.
 */
export function buildSeed(): DataState {
  return JSON.parse(JSON.stringify(raw)) as DataState;
}
